import csv

with open('outputs/t02_eurostat_raw.csv', 'r', encoding='utf-8', newline='') as f:
    reader = csv.reader(f)
    header = next(reader)
    for i, row in enumerate(reader):
        if len(row) != len(header):
            print(f'Row {i+2} has {len(row)} fields, expected {len(header)}')
            break
    else:
        print('All rows have correct number of fields')
